<?php require_once 'functions.php';require_role('buyer');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');verify_csrf();$p=(int)$_POST['product_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']);$pdo=db();$s=$pdo->prepare("INSERT INTO reviews(product_id,user_id,rating,comment) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)");$s->execute([$p,user()['id'],$rating,$comment]);flash('success','Review saved.');redirect('product.php?id='.$p);?>